package com.bank.grpc;

import com.bank.grpc.gen.*;
import com.google.gson.Gson;
import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.grpc.*;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ReliableTransferClient {
    private static final Logger log = Logger.getLogger(ReliableTransferClient.class.getName());
    private final AccountServiceGrpc.AccountServiceBlockingStub stub;
    private final CircuitBreaker breaker = CircuitBreaker.ofDefaults("transferCB");

    @SuppressWarnings("unchecked")
    public ReliableTransferClient(String serviceConfigJson) {
        Map<String, ?> config = new Gson().fromJson(serviceConfigJson, Map.class);
        ManagedChannel channel = ManagedChannelBuilder
            .forAddress("localhost", 9090).usePlaintext()
            .defaultServiceConfig(config)     // apply built-in retry policy
            .enableRetry()                    // turn on gRPC retries
            .keepAliveTime(30, TimeUnit.SECONDS)
            .build();
        this.stub = AccountServiceGrpc.newBlockingStub(channel);
    }

    public String transfer(String from, String to, String amount) {
        String idemKey = UUID.randomUUID().toString(); // dedupe retried mutations
        TransferRequest req = TransferRequest.newBuilder()
            .setFrom(from).setTo(to).setAmount(amount).setIdempotencyKey(idemKey).build();

        return breaker.executeSupplier(() -> {
            try {
                // DEADLINE: whole call must finish in 800ms, propagated downstream.
                TransferResponse resp = stub
                    .withDeadlineAfter(800, TimeUnit.MILLISECONDS)
                    .transfer(req);
                log.info(() -> "Transfer " + idemKey + " -> " + resp.getStatus());
                return resp.getStatus();
            } catch (StatusRuntimeException e) {
                Status.Code code = e.getStatus().getCode();
                // Distinguish retryable vs permanent using standardized codes.
                if (code == Status.Code.DEADLINE_EXCEEDED || code == Status.Code.UNAVAILABLE) {
                    log.log(Level.WARNING, "Retryable gRPC failure: " + code, e);
                } else {
                    log.log(Level.SEVERE, "Permanent gRPC failure: " + code, e);
                }
                throw e; // breaker counts it; fallback handled by caller
            }
        });
    }
}
